fixed_code:
# Letters must step through A, B, C in order without skipping a letter
string = input()
point_list = []
for x in string:
    point_list.append(ord(x))

code_point = point_list[0]

for x in point_list:
    if x == code_point:
        continue
    elif x == code_point + 1:
        code_point = x
    else:
        print('No')
        exit()

print('Yes')

